function shortestChain(start: string, target: string, words: string[]): number {
  const oneApart = (a: string, b: string): boolean => {
    let diff = 0;
    for (let i = 0; i < a.length && diff < 2; i++) if (a[i] !== b[i]) diff++;
    return diff === 1;
  };
  const used = new Array(words.length).fill(false);
  let level = [start], steps = 1;
  while (level.length) {
    steps++;
    const next: string[] = [];
    for (const w of level)
      for (let i = 0; i < words.length; i++)
        if (!used[i] && oneApart(w, words[i])) {
          if (words[i] === target) return steps;
          used[i] = true;
          next.push(words[i]);
        }
    level = next;
  }
  return 0;
}

