function shortestChain(start: string, target: string, words: string[]): number {
  const left = new Set(words); // words not visited yet
  if (!left.has(target)) return 0;
  const letters = "abcdefghijklmnopqrstuvwxyz";
  let level = [start], steps = 1;
  while (level.length) {
    steps++;
    const next: string[] = [];
    for (const w of level) {
      for (let i = 0; i < w.length; i++) {
        for (const ch of letters) {
          if (ch === w[i]) continue;
          const cand = w.slice(0, i) + ch + w.slice(i + 1);
          if (!left.has(cand)) continue;
          if (cand === target) return steps;
          left.delete(cand); // visited as soon as it is queued
          next.push(cand);
        }
      }
    }
    level = next;
  }
  return 0;
}

