function shortestChain(start: string, target: string, words: string[]): number {
  if (!words.includes(target)) return 0;
  const buckets = new Map<string, string[]>();
  for (const w of words)
    for (let i = 0; i < w.length; i++) {
      const key = w.slice(0, i) + "*" + w.slice(i + 1);
      if (!buckets.has(key)) buckets.set(key, []);
      buckets.get(key)!.push(w);
    }
  const seen = new Set([start]);
  let level = [start], steps = 1;
  while (level.length) {
    steps++;
    const next: string[] = [];
    for (const w of level)
      for (let i = 0; i < w.length; i++) {
        const key = w.slice(0, i) + "*" + w.slice(i + 1);
        for (const cand of buckets.get(key) || []) {
          if (seen.has(cand)) continue;
          if (cand === target) return steps;
          seen.add(cand);
          next.push(cand);
        }
        buckets.delete(key); // every word in it is now seen; never scan it again
      }
    level = next;
  }
  return 0;
}

